#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
​
using namespace std;
​
// 四个搜索方向：水平、垂直、主对角线、副对角线
const vector<vector<int>> DIRECTIONS = {{0, 1}, {1, 0}, {1, 1}, {-1, 1}};
​
// 计算从 (row, col) 出发，在四个方向上的最大连续 'M' 数量
int findMaxConnectedM(const vector<vector<string>>& grid, int row, int col) {
    // 至少起点为M
    int maxCount = 1; 
    int rows = grid.size();
    int cols = grid[0].size();
​
    for (const auto& dir : DIRECTIONS) {
        int count = 1, r = row, c = col;
        while (r + dir[0] >= 0 && r + dir[0] < rows && c + dir[1] >= 0 && c + dir[1] < cols
               && grid[r + dir[0]][c + dir[1]] == "M") {
            r += dir[0];
            c += dir[1];
            count++;
        }
​
        maxCount = max(maxCount, count);
    }
    return maxCount;
}
​
int main() {
    string input;
    getline(cin, input);

    // 解析行数和列数
    stringstream ss(input);
    string temp;
    getline(ss, temp, ',');
    int rows = stoi(temp);
    getline(ss, temp);
    int cols = stoi(temp);
​
    // 读取矩阵数据
    vector<vector<string>> grid(rows, vector<string>(cols));
    for (int i = 0; i < rows; ++i) {
        getline(cin, input);
        stringstream rowStream(input);
        for (int j = 0; j < cols; ++j) {
            getline(rowStream, grid[i][j], ',');
        }
    }
​
    int maxMCount = 0; // 记录最大的连续 'M' 数量
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            if (grid[i][j] == "M") {
                maxMCount = max(maxMCount, findMaxConnectedM(grid, i, j));
            }
        }
    }
​
    cout << maxMCount << endl; // 输出最大的连续 'M' 数量
    return 0;
}
