const readline = require("readline");
​
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
const DIRECTIONS = [[0, 1], [1, 0], [1, 1], [-1, 1]];
​
// 计算从 (row, col) 出发，在四个方向上的最大连续 'M' 数量
function findMaxConnectedM(grid, row, col) {
    let maxCount = 1;
    const rows = grid.length, cols = grid[0].length;
​
    for (const [dr, dc] of DIRECTIONS) {
        let count = 1, r = row, c = col;
        while (r + dr >= 0 && r + dr < rows && c + dc >= 0 && c + dc < cols && grid[r + dr][c + dc] === "M") {
            r += dr;
            c += dc;
            count++;
        }
        maxCount = Math.max(maxCount, count);
    }
    return maxCount;
}
​
const inputLines = [];
