​
    let maxMCount = 0;
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            if (grid[i][j] === "M") {
                maxMCount = Math.max(maxMCount, findMaxConnectedM(grid, i, j));
