package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
// 四个方向：水平、垂直、主对角线、副对角线
var directions = [][]int{{0, 1}, {1, 0}, {1, 1}, {-1, 1}}
​
// 计算从 (row, col) 出发，在四个方向上的最大连续 'M' 数量
func findMaxConnectedM(grid [][]string, row, col int) int {
    maxCount := 1
    rows, cols := len(grid), len(grid[0])
​
    for _, dir := range directions {
        count, r, c := 1, row, col
        for r+dir[0] >= 0 && r+dir[0] < rows && c+dir[1] >= 0 && c+dir[1] < cols && grid[r+dir[0]][c+dir[1]] == "M" {
            r += dir[0]
            c += dir[1]
            count++
        }
        if count > maxCount {
            maxCount = count
        }
    }
    return maxCount
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
​
    // 读取矩阵尺寸
    scanner.Scan()
    dimensions := strings.Split(scanner.Text(), ",")
    rows, _ := strconv.Atoi(dimensions[0])
    cols, _ := strconv.Atoi(dimensions[1])
​
    // 读取矩阵数据
    grid := make([][]string, rows)
    for i := 0; i < rows; i++ {
        scanner.Scan()
        grid[i] = strings.Split(scanner.Text(), ",")
    }
​
    maxMCount := 0
    for i := 0; i < rows; i++ {
        for j := 0; j < cols; j++ {
            if grid[i][j] == "M" {
                maxMCount = max(maxMCount, findMaxConnectedM(grid, i, j))
            }
        }
    }
​
    fmt.Println(maxMCount)
}
​
// 返回较大值
func max(a, b int) int {
    if a > b {
        return a
    }
    return b
}
